#!/usr/bin/env node
const fs = require("fs");
const path = require("path");
const root = path.resolve(__dirname, "..", "..");
const projectsRoot = path.join(root, "projects");
const imageExt = /\.(png|jpe?g|gif|webp|svg)$/i;
function safeId(value) { return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80) || "images"; }
function ensureDir(dir) { fs.mkdirSync(dir, { recursive: true }); }
function files(dir) { return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => { const full = path.join(dir, entry.name); if (entry.isDirectory()) return files(full); return imageExt.test(entry.name) ? [full] : []; }); }
function project(id) { return { dir: path.join(projectsRoot, id), inProcess: path.join(projectsRoot, id, "in-process"), done: path.join(projectsRoot, id, "done"), evidence: path.join(projectsRoot, id, "evidence") }; }
const [cmd, arg] = process.argv.slice(2);
if (cmd === "import") {
  if (!arg) { console.error("usage: cli.js import <image-directory>"); process.exit(1); }
  const source = path.resolve(arg);
  const id = safeId(path.basename(source)) + "-" + new Date().toISOString().slice(0,10).replace(/-/g, "");
  const p = project(id); ensureDir(p.inProcess); ensureDir(p.evidence);
  const images = files(source).map((file) => ({ path: file, relativePath: path.relative(source, file), bytes: fs.statSync(file).size }));
  const manifest = { id, source, imageCount: images.length, images };
  fs.writeFileSync(path.join(p.inProcess, "images.json"), JSON.stringify(manifest, null, 2) + "\n");
  fs.writeFileSync(path.join(p.evidence, "manifest.json"), JSON.stringify({ id, source, imageCount: images.length, createdAt: new Date().toISOString() }, null, 2) + "\n");
  console.log(JSON.stringify({ jobId: id, imageCount: images.length }));
} else if (cmd === "build") {
  if (!arg) { console.error("usage: cli.js build <job-id>"); process.exit(1); }
  const p = project(arg);
  const manifest = JSON.parse(fs.readFileSync(path.join(p.inProcess, "images.json"), "utf8"));
  ensureDir(p.done);
  const cards = manifest.images.map((img) => "<figure><img src=\"file://" + img.path + "\" loading=\"lazy\"><figcaption>" + img.relativePath + "</figcaption></figure>").join("\n");
  const html = "<!doctype html><meta charset=\"utf-8\"><title>Contact sheet " + manifest.id + "</title><style>body{font-family:sans-serif}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:1rem}img{max-width:100%;height:140px;object-fit:contain;border:1px solid #ddd}figcaption{font-size:12px;overflow-wrap:anywhere}</style><h1>Contact sheet</h1><p>" + manifest.imageCount + " images from " + manifest.source + "</p><main>" + cards + "</main>";
  const out = path.join(p.done, "contact-sheet.html");
  fs.writeFileSync(out, html);
  fs.writeFileSync(path.join(p.evidence, "outputs.json"), JSON.stringify({ output: out, imageCount: manifest.imageCount, finishedAt: new Date().toISOString() }, null, 2) + "\n");
  console.log(JSON.stringify({ ok: true, output: out, imageCount: manifest.imageCount }));
} else { console.error("usage: cli.js <import|build> ..."); process.exit(1); }

#!/usr/bin/env bash
set -euo pipefail
DIR=${1:?usage: workflow/01-import-images.sh <image-directory>}
ROOT=$(cd "$(dirname "$0")/.." && pwd)
node "$ROOT/tools/image-contact-sheet/cli.js" import "$DIR"

#!/usr/bin/env bash
set -euo pipefail
JOB_ID=${1:?usage: workflow/02-build-contact-sheet.sh <job-id>}
ROOT=$(cd "$(dirname "$0")/.." && pwd)
node "$ROOT/tools/image-contact-sheet/cli.js" build "$JOB_ID"
